create table if not exists _backup_20260830_player_external_ids_bad_age as
  select * from player_external_ids;

-- Deshacer las fusiones que se apoyaban en un transfermarkt_id ahora
-- inválido: cada fila (no-transfermarkt) del grupo vuelve a tener su
-- propia identidad.
do $do$
declare
  bad_tm_ids bigint[] := array[218,5819,7865,7897,13833,14380,14855,17563,41561,57947,82972,84606,99798,102149,102524,102711,125109,130026,200746,205146,214164,236161,255003,273210,305092,309237,310908,310979,358811,372355,508601,515148,631756,651852,706376,726174,732919,733397,739539,765926,766143,773827,786167,802101,805344,847687,855645,987588,1001409,1041289,1192335,1360219,1369831,1389110];
  r record;
  new_id bigint;
begin
  for r in
    select peid.id as ext_row_id
    from player_external_ids peid
    where peid.source != 'transfermarkt'
      and peid.player_identity_id in (
        select player_identity_id from player_external_ids
        where source = 'transfermarkt' and external_id = any(bad_tm_ids)
      )
  loop
    insert into player_identities default values returning id into new_id;
    update player_external_ids set player_identity_id = new_id where id = r.ext_row_id;
  end loop;

  delete from player_external_ids
  where source = 'transfermarkt' and external_id = any(bad_tm_ids);

  delete from player_identities pi
  where not exists (select 1 from player_external_ids x where x.player_identity_id = pi.id);
end $do$;

